const fs = require('fs');
const zlib = require('zlib');
const { Readable } = require('stream');

// Minimal ZIP parser to extract document.xml from docx
function readZipEntries(buf) {
  // Find End of Central Directory
  let eocdPos = -1;
  for (let i = buf.length - 22; i >= 0; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) {
      eocdPos = i;
      break;
    }
  }
  if (eocdPos === -1) return [];

  const cdOffset = buf.readUInt32LE(eocdPos + 16);
  const cdSize = buf.readUInt32LE(eocdPos + 12);
  const numEntries = buf.readUInt16LE(eocdPos + 10);

  let pos = cdOffset;
  const entries = [];
  for (let i = 0; i < numEntries; i++) {
    if (buf.readUInt32LE(pos) !== 0x02014b50) break;
    const compMethod = buf.readUInt16LE(pos + 10);
    const compSize = buf.readUInt32LE(pos + 20);
    const uncompSize = buf.readUInt32LE(pos + 24);
    const nameLen = buf.readUInt16LE(pos + 28);
    const extraLen = buf.readUInt16LE(pos + 30);
    const commentLen = buf.readUInt16LE(pos + 32);
    const localHeaderOffset = buf.readUInt32LE(pos + 42);
    const name = buf.toString('utf-8', pos + 46, pos + 46 + nameLen);
    entries.push({ name, compMethod, compSize, uncompSize, localHeaderOffset });
    pos += 46 + nameLen + extraLen + commentLen;
  }
  return entries;
}

function extractEntry(buf, entry) {
  const pos = entry.localHeaderOffset;
  const nameLen = buf.readUInt16LE(pos + 26);
  const extraLen = buf.readUInt16LE(pos + 28);
  const dataStart = pos + 30 + nameLen + extraLen;
  const rawData = buf.slice(dataStart, dataStart + entry.compSize);
  if (entry.compMethod === 0) return rawData;
  if (entry.compMethod === 8) return zlib.inflateRawSync(rawData);
  return null;
}

const files = [
  '/workspace/testbed/docs/customer_report.docx',
  '/workspace/testbed/docs/report.docx',
  '/workspace/testbed/docs/travel_summary.docx',
  '/workspace/testbed/docs/Meeting_Notes_2024_06.docx'
];

for (const f of files) {
  console.log('=== ' + f + ' ===');
  const buf = fs.readFileSync(f);
  const entries = readZipEntries(buf);
  const docEntry = entries.find(e => e.name === 'word/document.xml');
