const PDFDocument = require('pdfkit');
const fs = require('fs');

const doc = new PDFDocument({ margin: 50, size: 'A4' });
const out = fs.createWriteStream('/workspace/testbed/docs/maya_chen_customer_activity_report.pdf');
doc.pipe(out);

// Title
doc.fontSize(20).font('Helvetica-Bold').text('Customer Activity Report', { align: 'center' });
doc.moveDown(1.5);

// Customer info
doc.fontSize(16).font('Helvetica-Bold').text('Maya Chen');
doc.moveDown(0.3);
doc.fontSize(10).font('Helvetica')
  .text('Email: maya.chen@example.com')
  .text('Loyalty Tier: Gold')
  .text('Store Credit: $0');
doc.moveDown(1);

// Orders
const orders = [
  { id: 'ORD-6C71B1', status: 'cancelled', total: '$79',  items: 'Anker Portable Bluetooth Speaker' },
  { id: 'ORD-5B048F', status: 'confirmed', total: '$108', items: 'Anker Portable Bluetooth Speaker, LogiTech Wireless Mouse M310' },
  { id: 'ORD-12AAA3', status: 'cancelled', total: '$39',  items: 'Wireless Ergonomic Mouse' },
  { id: 'ORD-542FDA', status: 'confirmed', total: '$68',  items: 'OXO SoftWorks 3-Piece Mixing Bowl Set, ThermoPro Digital Meat Thermometer' },
  { id: 'ORD-D7E869', status: 'confirmed', total: '$71',  items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set' },
  { id: 'ORD-C31654', status: 'confirmed', total: '$29',  items: 'Wireless Mouse' },
  { id: 'ORD-CCC96C', status: 'confirmed', total: '$201', items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set, Aurora Smart Desk Lamp Pro' },
];

// Table header
const colX = { order: 50, date: 160, status: 260, total: 345, items: 400 };
const colW = { order: 110, date: 100, status: 85, total: 55, items: 145 };

function drawTableHeader(doc) {
  const y = doc.y;
  doc.fontSize(9).font('Helvetica-Bold');
  doc.rect(colX.order, y, 495, 20).fill('#3b5998');
  doc.fillColor('white');
  doc.text('Order', colX.order + 5, y + 5, { width: colW.order });
  doc.text('Date', colX.date + 5, y + 5, { width: colW.date });
  doc.text('Status', colX.status + 5, y + 5, { width: colW.status });
  doc.text('Total', colX.total + 5, y + 5, { width: colW.total });
  doc.text('Items', colX.items + 5, y + 5, { width: colW.items });
  doc.fillColor('black');
  doc.y = y + 22;
}

drawTableHeader(doc);

orders.forEach((order, i) => {
  const y = doc.y;
  // Calculate row height based on items text
  const itemsHeight = doc.fontSize(8).font('Helvetica').heightOfString(order.items, { width: colW.items - 10 });
  const rowHeight = Math.max(20, itemsHeight + 10);

  // Alternating row background
  if (i % 2 === 0) {
    doc.rect(colX.order, y, 495, rowHeight).fill('#f0f4fa');
    doc.fillColor('black');
  }

  doc.fontSize(8).font('Helvetica');
  doc.text(order.id, colX.order + 5, y + 5, { width: colW.order });
  doc.text('2026-09-02', colX.date + 5, y + 5, { width: colW.date });

  // Color-code status
  const statusColor = order.status === 'confirmed' ? '#2e7d32' : '#c62828';
  doc.fillColor(statusColor).text(order.status, colX.status + 5, y + 5, { width: colW.status });
  doc.fillColor('black');

  doc.text(order.total, colX.total + 5, y + 5, { width: colW.total });
  doc.text(order.items, colX.items + 5, y + 5, { width: colW.items - 10 });

  doc.y = y + rowHeight + 1;
});

// Summary
doc.moveDown(1.5);
doc.fontSize(10).font('Helvetica-Bold').text('Summary');
doc.moveDown(0.3);
doc.fontSize(9).font('Helvetica');
doc.text('Total Orders: 7  |  Confirmed: 5  |  Cancelled: 2');
doc.text('Grand Total (all orders): $595');

doc.end();

out.on('finish', () => {
  console.log('PDF created: /workspace/testbed/docs/maya_chen_customer_activity_report.pdf');
});
